def move_secrets_to_devices(apps, schema_editor):
    """Each user's single authenticator becomes their first device."""
    from django.utils import timezone

    User = apps.get_model("accounts", "User")
    Device = apps.get_model("accounts", "AuthenticatorDevice")
    now = timezone.now()
    for user in User.objects.filter(is_2fa_enabled=True).exclude(totp_secret=""):
        Device.objects.create(user=user, name="Authenticator app", secret=user.totp_secret, confirmed_at=now)
    # A secret without 2FA on was an unfinished setup; dropping it is harmless.


def restore_secrets(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    Device = apps.get_model("accounts", "AuthenticatorDevice")
    for device in Device.objects.filter(confirmed_at__isnull=False).order_by("user_id", "created_at"):
        user = User.objects.get(pk=device.user_id)
        if not user.totp_secret:
            user.totp_secret = device.secret
            user.save(update_fields=["totp_secret"])


